    deg = False
    list_of_inputs.append({"z": copy.deepcopy(z), "deg": deg})

    # Input 8: 1D purely imaginary complex64, degrees
    z = np.array([1j, 2j, -3j, -4j], dtype=np.complex64)
    deg = True
    list_of_inputs.append({"z": copy.deepcopy(z), "deg": deg})

