    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 4: 3D array with some values outside [-1, 1] to test nan behavior, float32
    x = np.array([[[ -2.0, 0.0], [0.5, 2.0]], [[-0.1, 0.1], [1.5, -1.5]]], dtype=np.float32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

