    # Input 5: Special values (zeros with different signs)
    x1 = np.array([0.0, -0.0, 0.0], dtype=np.float32)
    x2 = np.array([-1.0, 1.0, -1.0], dtype=np.float32)
    list_of_inputs.append({"x1": x1, "x2": x2})

    # Input 6: Special values (Infs and NaNs)
