# Patch jax.numpy.cosh to accept tuples by converting them to JAX arrays
orig_cosh = jnp.cosh

def patched_cosh(x, *args, **kwargs):
    if isinstance(x, tuple):
        x = jnp.asarray(x)
    return orig_cosh(x, *args, **kwargs)

jnp.cosh = patched_cosh
