    b = np.random.randn(3).astype(np.float64)
    input_dict = {
        "a": a,
        "b": b,
        "axisa": -1,
        "axisb": -1,
        "axisc": -1,
        "axis": -1
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

