    list_of_inputs.append(copy.deepcopy({"x": float('inf'), "y": float('inf')}))

    # Input 8: Positive and negative infinity comparison
    list_of_inputs.append(copy.deepcopy({"x": float('-inf'), "y": float('inf')}))

