    input_dict = {"x": x, "y": y}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Broadcast compatible, 2D and 1D
    x = np.array([[2, -4, 1], [-1, 2, 3]], dtype=np.float32)
