    input_dict = {"x": x, "y": y}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: 3D tensors, same shape
    x = np.random.uniform(1.0, 5.0, size=(2, 3, 4)).astype(np.float32)
