    input_dict = {"x": x, "y": y}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: Broadcasting with 1s in dimensions
    x = np.random.uniform(1.0, 5.0, size=(1, 3, 1)).astype(np.float32)
