    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 3: 3D complex64 array
    x = (np.random.randn(2, 2, 2) + 1j * np.random.randn(2, 2, 2)).astype(np.complex64)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 4: 1D int32 array
    x = np.array([-10, 0, 10, 20]).astype(np.int32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

