# Monkeypatch JAX's internal _isposneginf to support the 'out' argument
def patched_isposneginf(infval, x, out):
    res = (x == infval)
    if out is not None:
        try:
            if isinstance(out, np.ndarray):
                np.copyto(out, np.array(res))
        except Exception:
            pass
    return res

