import jax.numpy as jnp
import numpy as np
import copy

orig_isreal = jnp.isreal

def patched_isreal(x):
    if isinstance(x, tuple):
        x = jnp.array(x)
    return orig_isreal(x)

jnp.isreal = patched_isreal
jax.numpy.isreal = patched_isreal

