import numpy as np
import copy
import jax.numpy as jnp

_original_put = jnp.put

def patched_put(a, ind, v, mode=None, *, inplace=True):
    if isinstance(ind, tuple):
        ind = np.array(ind, dtype=np.int32)
    return _original_put(a, ind, v, mode=mode, inplace=inplace)

jnp.put = patched_put

