import numpy as np
import copy

def jax_numpy_square_inputs():
    list_of_inputs = []

    # Input 1: 1D float32 array
    x = np.array([3.0, -2.0, 5.3, 1.0], dtype=np.float32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 2: 2D int32 array
    x = np.array([[2, 4], [5, 6]], dtype=np.int32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 3: 1D complex64 array
    x = np.array([1 - 3j, -1j, 2], dtype=np.complex64)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 4: 3D float64 array
    x = np.random.randn(2, 3, 4).astype(np.float64)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 5: 0D float32 array
    x = np.array(4.5, dtype=np.float32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 6: 4D int16 array
    x = np.random.randint(-10, 10, size=(2, 2, 2, 2)).astype(np.int16)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 7: 2D float16 array
    x = np.random.randn(3, 3).astype(np.float16)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 8: 1D int64 array
    x = np.array([0, -1, 2, -3, 4], dtype=np.int64)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 9: 5D float32 array
    x = np.random.randn(2, 1, 3, 1, 2).astype(np.float32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 10: 2D complex128 array
    x = np.array([[1 + 1j, 2 - 2j], [3 + 3j, 4 - 4j]], dtype=np.complex128)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    # Input 11: 1D float32 array containing special float values
    x = np.array([0.0, -0.0, np.inf, -np.inf, np.nan], dtype=np.float32)
    list_of_inputs.append({"x": copy.deepcopy(x)})

    return list_of_inputs

generated_inputs["jax.numpy.square_1"] = jax_numpy_square_inputs()

import numpy as np
import copy

def square_inputs():
    list_of_inputs = []

    # Input 1: Simple positive python integer
    input_dict = {"x": 5}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: Negative python integer
    input_dict = {"x": -10}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Zero python integer
    input_dict = {"x": 0}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: 0D numpy array (scalar) of type np.int32
    input_dict = {"x": np.array(42, dtype=np.int32)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: 1D numpy array of np.int64
    input_dict = {"x": np.array([1, -2, 3, -4], dtype=np.int64)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: 2D numpy array of np.int32
    input_dict = {"x": np.array([[1, 2], [3, 4]], dtype=np.int32)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: 3D numpy array of np.int16
    input_dict = {"x": np.array([[[1, -1], [2, -2]], [[3, -3], [4, -4]]], dtype=np.int16)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 1D numpy array of np.int8
    input_dict = {"x": np.array([-128, 0, 127], dtype=np.int8)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: Large positive python integer
    input_dict = {"x": 1000}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 10: 2D numpy array of np.uint32 (unsigned integer)
    input_dict = {"x": np.array([[10, 20], [30, 40]], dtype=np.uint32)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 11: 1D numpy array of np.uint16
    input_dict = {"x": np.array([0, 1, 500], dtype=np.uint16)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

