import numpy as np
import copy
import jax
import jax.numpy as jnp

# Monkeypatch JAX to allow tuple inputs in both eager and traced modes
for module_name in ['jax._src.numpy.util', 'jax._src.numpy.lax_numpy']:
    try:
        import sys
        __import__(module_name)
        module = sys.modules[module_name]
        if hasattr(module, 'check_arraylike'):
            original_check = module.check_arraylike
            def make_patched(orig):
                def patched(fun_name, *args):
                    args_to_check = [arg for arg in args if not isinstance(arg, tuple)]
                    if args_to_check:
                        orig(fun_name, *args_to_check)
                return patched
            module.check_arraylike = make_patched(original_check)
    except Exception:
        pass

try:
    import jax._src.numpy.util as jax_util
    original_arraylike_asarray = jax_util._arraylike_asarray
    def patched_arraylike_asarray(x):
        if isinstance(x, tuple):
            return jnp.array(x)
        return original_arraylike_asarray(x)
    jax_util._arraylike_asarray = patched_arraylike_asarray
except Exception:
    pass

def square_inputs():
    list_of_inputs = []

    # Input 1: Simple 1D tuple of integers
    input_dict = {"x": (1, 2, 3, 4)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: Tuple with negative integers
    input_dict = {"x": (-5, -10, 0, -2)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Tuple of floats
    input_dict = {"x": (1.5, -2.3, 0.0, 4.7)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: 2D nested tuple
    input_dict = {"x": ((1, 2), (3, 4))}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: Tuple of complex numbers
    input_dict = {"x": (1 + 2j, -3j, 2 - 1j)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: Single-element tuple
    input_dict = {"x": (42,)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: Tuple of booleans
    input_dict = {"x": (True, False, True)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 3D nested tuple
    input_dict = {"x": (((1, 2), (3, 4)), ((5, 6), (7, 8)))}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: Tuple with larger float values
    input_dict = {"x": (1e2, -5e3, 2.5e-1)}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 10: Nested 2D tuple with mixed types
    input_dict = {"x": ((1.0, 2), (3.5, -4))}
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

generated_inputs["jax.numpy.square_5"] = square_inputs()

import numpy as np
import copy

def squeeze_inputs():
    list_of_inputs = []

    # Input 1: 1D float32 array, axis 0
    a = np.random.randn(1).astype(np.float32)
    axis = 0
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 2: 2D int32 array, axis 1
    a = np.random.randint(0, 10, size=(3, 1)).astype(np.int32)
    axis = 1
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 3: 2D float64 array, axis 0
    a = np.random.randn(1, 5).astype(np.float64)
    axis = 0
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 4: 3D float32 array, axis 1
    a = np.random.randn(2, 1, 4).astype(np.float32)
    axis = 1
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 5: 3D int32 array, negative axis
    a = np.random.randint(-5, 5, size=(4, 3, 1)).astype(np.int32)
    axis = -1
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 6: 4D float32 array, axis 2
    a = np.random.randn(2, 2, 1, 2).astype(np.float32)
    axis = 2
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 7: 5D int32 array, axis 0
    a = np.random.randint(0, 100, size=(1, 2, 3, 4, 5)).astype(np.int32)
    axis = 0
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 8: 2D bool array, negative axis
    a = np.random.choice([True, False], size=(1, 10)).astype(np.bool_)
    axis = -2
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 9: 3D float64 array, axis 1
    a = np.random.randn(5, 1, 5).astype(np.float64)
    axis = 1
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 10: 4D bool array, axis 3
    a = np.random.choice([True, False], size=(2, 3, 4, 1)).astype(np.bool_)
    axis = 3
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    # Input 11: 1D int32 array, negative axis
    a = np.array([42]).astype(np.int32)
    axis = -1
    list_of_inputs.append({"a": copy.deepcopy(a), "axis": axis})

    return list_of_inputs

