import numpy as np
import jax
from jax.sharding import PartitionSpec, Mesh
import copy

# Set up a global mesh context so PartitionSpec can be canonicalized
devices = np.array(jax.devices())
mesh = Mesh(devices, ('x',))
mesh_ctx = jax.set_mesh(mesh)
mesh_ctx.__enter__()

def zeros_inputs():
    list_of_inputs = []

    shapes = [10, 5, 100, 1, 1000, 2, 8, 50, 256, 12]
    dtypes = [
        np.float32, 
        np.int32, 
        np.float64, 
        np.bool_, 
        np.int64,
        np.complex64, 
        np.uint8, 
        np.int16, 
        np.uint32, 
        np.int8
    ]

    for i in range(10):
        # Use empty PartitionSpec() to avoid numpy min/max errors in the test framework
        input_dict = {
            "shape": shapes[i],
            "dtype": dtypes[i],
            "out_sharding": PartitionSpec()
        }
        list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

